function validate([blocks, k]) {
  if (blocks.length < 1 || blocks.length > 100) return 'blocks needs 1 to 100 characters.';
  if (!/^[WB]+$/.test(blocks)) return "blocks may only contain 'W' and 'B'.";
  if (!Number.isInteger(k) || k < 1 || k > blocks.length) return 'k must be between 1 and the length of blocks.';
  return null;
}

