function minimumRecolors(blocks, k) {
  let whites = 0;
  for (let i = 0; i < k; i++) {
    if (blocks[i] === 'W') whites++;
  }
  let best = whites;
  for (let right = k; right < blocks.length; right++) {
    if (blocks[right] === 'W') whites++;
    if (blocks[right - k] === 'W') whites--;
    best = Math.min(best, whites);
  }
  return best;
}

