function minimumRecolors(blocks, k) {
  let best = Infinity;
  for (let start = 0; start + k <= blocks.length; start++) {
    const piece = blocks.slice(start, start + k);
    best = Math.min(best, piece.split('').filter(ch => ch === 'W').length);
  }
  return best;
}

