function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 10);
  // Vary how dark the row is, from almost all white to almost all black.
  const blackShare = rand();
  let blocks = '';
  for (let i = 0; i < n; i++) blocks += rand() < blackShare ? 'B' : 'W';
  const k = 1 + Math.floor(rand() * n);
  return [blocks, k];
}
